#include<cstdint>
#include<initializer_list>
namespace mal{namespace number_theory{using u64=std::uint64_t;inline u64 mul_mod(u64 a,u64 b,u64 mod){return u64((unsigned __int128)a*b%mod);}inline u64 pow_mod(u64 a,u64 k,u64 mod){if(!mod)return 0;u64 result=1%mod;for(a%=mod;k;k>>=1,a=mul_mod(a,a,mod))if(k&1)result=mul_mod(result,a,mod);return result;}inline bool is_prime(u64 n){if(n<2)return false;for(u64 p:{2ULL,3ULL,5ULL,7ULL,11ULL,13ULL,17ULL,19ULL,23ULL,29ULL,31ULL,37ULL}){if(n%p==0)return n==p;}u64 d=n-1;int s=0;while(!(d&1))d>>=1,++s;for(u64 a:{2ULL,325ULL,9375ULL,28178ULL,450775ULL,9780504ULL,1795265022ULL}){if(a%n==0)continue;u64 x=pow_mod(a,d,n);if(x==1||x==n-1)continue;bool witness=true;for(int r=1;r<s;++r){x=mul_mod(x,x,n);if(x==n-1){witness=false;break;}}if(witness)return false;}return true;}namespace detail{__attribute__((used))auto mul_mod_kept=&mul_mod;__attribute__((used))auto pow_mod_kept=&pow_mod;__attribute__((used))auto is_prime_kept=&is_prime;}}}
#include<vector>
#include<utility>
#include<stdexcept>
namespace mal{namespace number_theory{struct Sieve{std::vector<int>spf,primes;explicit Sieve(int n);bool prime(int x)const;std::vector<std::pair<int,int>>factor(int x)const;};inline Sieve::Sieve(int n):spf(n>=0?n+1:0){if(n<0)throw std::invalid_argument("sieve: negative limit");for(int i=2;i<=n;++i){if(!spf[i])spf[i]=i,primes.push_back(i);for(int p:primes){if(p>spf[i]||1LL*i*p>n)break;spf[i*p]=p;}}}inline bool Sieve::prime(int x)const{if(x<0||x>=int(spf.size()))throw std::out_of_range("sieve: outside table");return x>=2&&spf[x]==x;}inline std::vector<std::pair<int,int>>Sieve::factor(int x)const{if(x<1||x>=int(spf.size()))throw std::out_of_range("sieve: outside table");std::vector<std::pair<int,int>>result;while(x>1){int p=spf[x],e=0;do{x/=p;++e;}while(x>1&&spf[x]==p);result.emplace_back(p,e);}return result;}inline Sieve make_sieve(int n){return Sieve(n);}inline std::vector<int>totients(const Sieve&s){int n=int(s.spf.size())-1;std::vector<int>phi(n+1);if(n>=1)phi[1]=1;for(int i=2;i<=n;++i){int p=s.spf[i],m=i/p;phi[i]=(m%p==0)?phi[m]*p:phi[m]*(p-1);}return phi;}inline std::vector<int>mobius(const Sieve&s){int n=int(s.spf.size())-1;std::vector<int>mu(n+1);if(n>=1)mu[1]=1;for(int i=2;i<=n;++i){int p=s.spf[i],m=i/p;mu[i]=(m%p==0)?0:-mu[m];}return mu;}namespace detail{__attribute__((used))auto make_sieve_kept=&make_sieve;__attribute__((used))auto sieve_prime_kept=&Sieve::prime;__attribute__((used))auto sieve_factor_kept=&Sieve::factor;__attribute__((used))auto totients_kept=&totients;__attribute__((used))auto mobius_kept=&mobius;}}}
